from h34 import *
M=mcq;F=tf;S=short;N=num
b='<rect x="10" y="10" width="560" height="260" rx="10" fill="#f6fbf0" stroke="#333" stroke-width="2"/><circle cx="290" cy="140" r="52" fill="#d6f0c8" stroke="#2a7d3a" stroke-width="3"/><text x="290" y="135" text-anchor="middle" font-weight="bold">Plants</text><text x="290" y="156" text-anchor="middle" font-size="14">give us</text>'
for (x,y,t) in ((60,40,"Shade"),(250,24,"Fresh air"),(430,40,"Fruits, vegetables"),(40,140,"Medicine"),(440,140,"Wood for houses"),(60,230,"Fibre for clothes"),(250,246,"Shelter for animals"),(430,230,"Food for animals")):
    b+=f'<rect x="{x}" y="{y}" width="120" height="30" rx="14" fill="#fff3d6" stroke="#333"/><text x="{x+60}" y="{y+20}" text-anchor="middle" font-size="13">{t}</text>'
svgfile('c3-harmony-uses.svg',580,280,b)
chapter(3,'evs','living-in-harmony','Living in Harmony',
 ("The Mango Tree","One day little Shambhu was walking through the forest with his father. They sat down in the cool shade of a huge mango tree, which was home to birds, squirrels, monkeys and many other animals. Shambhu saw a monkey eating a mango and throwing away the seed. That small moment shows how plants, animals and we depend on each other."),
 [("Animals and plants around our homes",["We bring some animals and plants into our homes, and some start living in our homes on their own. Sometimes we share our home with them happily, but sometimes we do not like them in our home.","We take care of the animals and plants in our homes by giving them water, food and shelter.","Some animals, birds and insects visit our homes without being invited. We can talk with a partner about which ones come, why they come, how we feel and which we like.","Even when we do not like an animal or are scared of it, we must not hurt it. Animals generally do not hurt others unless they feel threatened by us."]),
  ("The mango tree story",["The mango tree was home to birds, squirrels, monkeys and many other animals. A tree can be a house for many living things.","Shambhu saw a monkey eating a mango and throwing out the seed. His father explained that a new plant would grow from this seed. This is how animals and plants help each other.","Shambhu picked up a mango that had fallen from the tree and said that he had also got a mango.","His father said we get fruits and vegetables from plants, and also medicines, fibre for clothes and wood for our houses."]),
  ("Uses of plants",["Plants give us many things. They give us shade, fruits, fresh air, medicine, wood and fibre.","Plants also give shelter to animals, and give food to animals.","Cotton and jute are plant fibres that we use for making clothes and ropes, and wood from trees is used to make doors, tables and houses.","Because plants give us so much, we should plant trees, water them and not break their branches or pluck flowers needlessly.","Think of a mango tree: its fruit feeds us, its leaves give shade, and its branches hold birds' nests."]),
  ("We need each other",["We give care, protection, food and shelter to animals and plants, and we get many things from them as well.","From cows, buffaloes and goats we get milk and loving company. That is why we respect these animals and treat them with kindness, care and compassion.","Animals and plants depend on each other too. They need each other for food and shelter.","Animals help plants by dispersing, which means spreading, their seeds. They also make the soil fertile by their waste, which means the soil becomes rich so that plants grow well. This helps plants to grow and spread near and far."]),
  ("Squirrels plant trees",["Thousands of trees are planted by squirrels by accident. They bury nuts and then forget where they hid them.","The buried nuts grow into new trees. This is one way animals and plants keep harmony and balance in nature.","Harmony means living together peacefully, helping and not harming each other.","When we put out water for birds in summer, or avoid breaking nests, we are keeping harmony too.","Remember: every living thing, big or small, has a place in our world and needs our kindness."]),
  ("Activities: know an animal, ants and a plant friend",["We can choose an animal or bird we see often, such as a goat, cow, dog, cat, crow, pigeon, sparrow, parrot or duck, and watch it closely, perhaps keeping a bowl of water and some grains for it.","We can note its name, where and when we saw it, how it moves, what sounds it makes and what it eats, and share the story with our classmates.","In the ant activity we place three kinds of food, a sweet like sugar or jaggery, something fried like a papad and something cooked like rice, a foot apart on the floor and watch which one the ants go to first.","We can make friends with a plant. When we are happy or sad we can go to our plant friend and share our feelings. We should care for the plant, and animals need our care too."]),
  ("A true story from Valparai",["Valparai is a small town in Tamil Nadu. All through the school year, children and teachers look for and record the birds that come to their town.","In the cold winter months, a bird called the Grey Wagtail (Vaalatti kuruvi in Tamil) arrives from the mountains to the warmer parts of India, and stays for a few months.","When the first Grey Wagtails arrive, the children and teachers welcome them with posters and share sweets with everyone.","This shows that we can love and welcome the birds and animals who share our world, and live in harmony with them."])],
 [("How does a mango seed become a new tree with the help of an animal?",[("A monkey eats a mango and throws away the seed.","The seed is the part from which a new plant can grow."),("The seed lands on the soil and, with water and sunlight, starts to sprout.","A seed needs soil, water and sunlight."),("The sprout grows into a new mango tree. This is how animals help plants by spreading seeds.","The animal helped to spread the seed, a process called dispersal.")]),
  ("Do the ant activity: which food will the ants go to first?",[("Place a sweet, a fried and a cooked food in a line, a foot apart.","Placing the foods apart lets us see which one is chosen."),("Make a guess before you watch: which one will they come to first?","A guess is a prediction we can check."),("Watch for some time, then say what happened and why you think so.","We learn by watching carefully, and ants like sweet foods.")])],
 ("Tell a friend how we depend on plants and animals, and how they depend on us.",["Plants give us food, shade, medicine, wood, fibre and fresh air","Animals give us milk and companionship and help plants by spreading seeds","We give them food, water, shelter and care","We should not hurt animals or plants"],["Plants and animals do not need us","We can hurt animals we do not like","Animals do not help plants"]),
 ["Plants give us food, shade, medicine, wood, fibre and fresh air.","Animals give us milk and company and help plants by spreading seeds and making the soil fertile.","We care for animals and plants by giving them food, water and shelter.","We must not hurt animals even if we are scared of them.","Squirrels plant trees by forgetting where they buried nuts.","In Valparai, children welcome the Grey Wagtail birds each winter."],
 [M("lh-1",1,"What did the monkey do with the mango seed in Shambhu's story?","Threw it away, so a new plant could grow",[("Ate it","The monkey ate the mango and threw out the seed."),("Gave it to Shambhu","The monkey did not give it away."),("Planted a flower","The seed grows into a mango tree.")],"A seed thrown away can grow into a new plant.",None),
  M("lh-2",1,"Which of these do we get from plants?","Fruits, medicine and wood",[("Milk","We get milk from animals like cows."),("Only water","Plants give many things."),("Nothing","Plants give us many useful things.")],"Plants give us food, medicine, fibre, wood and fresh air.",None),
  M("lh-3",1,"From which animals do we get milk?","Cows, buffaloes and goats",[("Squirrels","Squirrels do not give milk for us."),("Crows","Crows are birds."),("Ants","We do not get milk from ants.")],"We get milk from cows, buffaloes and goats.",None),
  F("lh-4",1,"We should hurt animals we are afraid of.",False,"We must not hurt animals, even if we are scared. They hurt only when they feel threatened."),
  M("lh-5",1,"What helps spread seeds far away from the plant?","Animals",[("Stones","Stones do not move seeds."),("Houses","Houses do not move seeds."),("Chairs","Chairs do not move seeds.")],"Animals carry and drop seeds, spreading plants near and far.",None),
  M("lh-6",2,"What do we mean when we say animals make the soil fertile?","Their waste makes the soil rich so plants grow well",[("They make the soil hard","Fertile soil is rich, not hard."),("They remove the soil","They do not remove the soil."),("They make it salty","Fertile soil is full of nutrients.")],"Animal waste adds nutrients to the soil.",None),
  M("lh-7",2,"Which bird do the children of Valparai welcome every winter?","The Grey Wagtail",[("The crow","Crows live there throughout the year."),("The parrot","The Grey Wagtail is the bird they welcome."),("The pigeon","The story is about Grey Wagtails.")],"The Grey Wagtail, called Vaalatti kuruvi in Tamil, comes in winter.",None),
  M("lh-8",2,"How do squirrels plant trees by accident?","They bury nuts and forget where they put them",[("They plant seeds on purpose","They forget the nuts by accident."),("They carry trees","They do not carry whole trees."),("They eat all the nuts","Forgotten nuts can grow.")],"The buried nuts grow into new trees.",None),
  S("lh-10",2,"Living together peacefully, helping and not harming each other is called ____.",["harmony","living in harmony"],"Harmony means living together peacefully.",[("hurry","Harmony is peace and balance, not hurry.")]),
  M("lh-9",3,"We give animals and plants food, water and shelter. Why is this important?","They depend on us for care",[("Because they will fight us","They do not fight us if we care."),("Because they do not need anything","All living things need food, water and shelter."),("Because it is a game","It is care, not a game.")],"Animals and plants we keep depend on us for their needs.",None),
  F("lh-11",3,"Plants and animals do not depend on each other.",False,"They depend on each other for food and shelter, and animals help plants spread seeds."),
  M("lh-12",3,"Which is a good way to be a friend to a tree?","Water it and care for it, and talk about your feelings to it",[("Break its branches","That harms the tree."),("Carve your name on it","That hurts the tree."),("Ignore it","A friend cares.")],"A tree can be a friend that we care for.",None)],
 svgs=[("c3-harmony-uses","A picture showing what plants give us","Uses of plants: shade, fresh air, fruit, medicine, wood, fibre and shelter.")])
